const VERSION="b0c94fbfa9fbc8c6";
const ASSETS=["assistant-document-ui.mjs","assistant-document.css","assistant-guide.mjs","assistant-job-ui.mjs","assistant-launcher.mjs","assistant-media-ui.mjs","assistant-model-state.mjs","assistant-preview-ui.mjs","assistant-ui.mjs","business-fields.js","business-time.mjs","context-hints.mjs","counter-write.js","document-photo-table.mjs","document-sheet-worker.js","erp-stocktake-ui.mjs","field-drafts.mjs","guided-tour.mjs","interface-entry.js","item-codes-ui.mjs","item-storage-ui.mjs","live-inventory.mjs","mobile-count-draft.mjs","mobile-icon-192.png","mobile-icon-512.png","mobile-offline.mjs","mobile-operations-ui.mjs","mobile-pwa.mjs","mobile-revalidate.mjs","mobile-scene.mjs","mobile.css","mobile.html","mobile.mjs","mobile.webmanifest","random-id.js","request-bridge.js","route-layer.mjs","route-preview-ui.mjs","scan-code-ui.mjs","stocktake-ui.mjs","stocktake.css","team-tasks-ui.mjs","vendor/jsQR.js","vendor/jsm/controls/OrbitControls.js","vendor/jsm/loaders/GLTFLoader.js","vendor/jsm/utils/BufferGeometryUtils.js","vendor/three.module.js","warehouse-code.mjs","warehouse-work-ui.mjs","warehouse-work.css","work-request.mjs","work-status.mjs","work-tasks-ui.mjs","../../../packages/three-kit/sku-capacity.mjs","../../../packages/three-kit/spaceGenerator.js","../../../packages/three-kit/warehouse-route.mjs"];
const ROOT=new URL('./',self.location.href);
const PREFIX='spatial-mobile-static:'+ROOT.pathname+':';
const CACHE=PREFIX+VERSION;
const ALLOWED=new Set(ASSETS.map(path=>new URL(path,ROOT).href));
const MOBILE=new URL('mobile.html',ROOT).href;
const RUNTIME=new URL('../../../runtime.js',ROOT).href;
ALLOWED.add(RUNTIME);
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const url of ALLOWED){const response=await fetch(url,{cache:'reload'});if(!response.ok||response.redirected)throw Error('离线资源未就绪');await cache.put(url,response);}})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith(PREFIX)&&key!==CACHE)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==ROOT.origin)return;const plain=url.origin+url.pathname;if(plain!==MOBILE&&!ALLOWED.has(request.url))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);if(plain===RUNTIME){try{const response=await fetch(request);if(response.ok&&!response.redirected)await cache.put(RUNTIME,response.clone());return response;}catch(error){const saved=await cache.match(RUNTIME);if(saved)return saved;throw error;}}return await cache.match(plain===MOBILE?MOBILE:request.url)||fetch(request);})());});
